function paginateParams(array $params, int $page, int $perPage): array
{
    $result = ['page' => $page, 'per_page' => $perPage];

    foreach ($params as $key => $value) {
        $result[$key] = $value;
    }

    return $result;
}

tasks.test_suite:
expect('adds page and per_page to empty params', paginateParams([], 2, 25), ['page' => 2, 'per_page' => 25]);
expect('preserves existing filters', paginateParams(['status' => 'paid'], 2, 25), ['status' => 'paid', 'page' => 2, 'per_page' => 25]);
expect('caller page wins over stale value', paginateParams(['status' => 'paid', 'page' => 1, 'per_page' => 10], 4, 50), ['status' => 'paid', 'page' => 4, 'per_page' => 50]);
expect('chaining moves to the next page', paginateParams(paginateParams(['status' => 'paid'], 1, 25), 2, 25), ['status' => 'paid', 'page' => 2, 'per_page' => 25]);

tasks.solution:
function paginateParams(array $params, int $page, int $perPage): array
{
    unset($params['page'], $params['per_page']);

    $params['page'] = $page;
    $params['per_page'] = $perPage;

    return $params;
}
